(()=>{var e=new WebSocket("wss://sdex-alb-664814673.ap-southeast-2.elb.amazonaws.com/ws");e.onopen=function(){console.log("Connected to WebSocket"),document.getElementById("status").textContent="Connected to WebSocket",e.send(JSON.stringify({type:"subscribe",channel:"orders"}))},e.onmessage=function(e){console.log("Received:",e.data),"orderBook"===JSON.parse(e.data).type&&(document.getElementById("status").textContent="Order book received")},e.onerror=function(e){console.error("WebSocket error:",e),document.getElementById("status").textContent="WebSocket error: "+e}})();